import React from 'react';

import {
  StyledSingleDimensionIcon,
  StyledOuterHighlightedIcon,
  StyledInnerHighlightedIcon,
} from './styles/DataPointShape.styles.js';

/** @internal */
export interface SingleDataPointShapeProps {
  active?: boolean;
  color: string;
}

/** @internal */
export const SingleDataPointShape = ({
  color,
  active = false,
}: SingleDataPointShapeProps) => {
  return active ? (
    <StyledOuterHighlightedIcon color={color} singleLine>
      <StyledInnerHighlightedIcon color={color} singleLine />
    </StyledOuterHighlightedIcon>
  ) : (
    <StyledSingleDimensionIcon color={color} />
  );
};

SingleDataPointShape['displayName'] = 'SingleDataPointShape';
